export class Order {
  id: OrderId;
  customer: Customer;          // direct object ref to another aggregate
  lineItems: LineItem[];
  shipment: Shipment;          // direct object ref to another aggregate
  payment: Payment;            // direct object ref to another aggregate
  customerNotes: CustomerNote[]; // CRM concern inside Order

  addLineItem(item: LineItem) {
    this.lineItems.push(item); // no invariant check
  }

  updateShipmentAddress(addr: Address) {
    this.shipment.address = addr; // mutates nested aggregate directly
  }

  confirmPayment(paymentId: string) {
    this.payment.status = 'CONFIRMED'; // mutates nested aggregate directly
  }
}
